    float sensor_data[32];
    for (int i = 0; i < 32; i++) {
        sensor_data[i] = (float)(i + 1) * 1.5f;
    }

    // Test channel 0 (first element)
    float result = get_sensor_value(sensor_data, 0);
    if (result != 1.5f) {
        printf("Test case 1 failed: Expected 1.5f, got %f\n", result);
        return 1;
    }

    // Test channel 15 (middle element)
    result = get_sensor_value(sensor_data, 15);
    if (result != 24.0f) {
        printf("Test case 2 failed: Expected 24.0f, got %f\n", result);
        return 1;
    }

    // Test channel 31 (last valid element)
    result = get_sensor_value(sensor_data, 31);
    if (result != 48.0f) {
        printf("Test case 3 failed: Expected 48.0f, got %f\n", result);
        return 1;
    }

    // Test case 2: Boundary conditions
    // Test with minimal values
    for (int i = 0; i < 32; i++) {
        sensor_data[i] = 0.0f;
    }
    result = get_sensor_value(sensor_data, 0);
    if (result != 0.0f) {
        printf("Test case 4 failed: Expected 0.0f, got %f\n", result);
        return 1;
    }

    // Test with maximum values
    for (int i = 0; i < 32; i++) {
        sensor_data[i] = 999.99f;
    }
    result = get_sensor_value(sensor_data, 31);
    if (result != 999.99f) {
        printf("Test case 5 failed: Expected 999.99f, got %f\n", result);
        return 1;
    }

    // Test case 3: Negative values
    for (int i = 0; i < 32; i++) {
        sensor_data[i] = -10.0f + (float)i;
    }
    result = get_sensor_value(sensor_data, 10);
    if (result != 0.0f) { // -10.0 + 10 = 0.0
        printf("Test case 6 failed: Expected 0.0f, got %f\n", result);
        return 1;
    }

    printf("All function tests passed!\n");
    return 0;
}

