#include "sensor_handler.h"
#include <stdio.h>

int main() {
    float sensor_data[32];
    for (int i = 0; i < 32; i++) {
        sensor_data[i] = (float)(i + 1);
    }

    // Test out-of-bounds read with negative index
    printf("Testing negative index: -1\n");
    volatile float result1 = get_sensor_value(sensor_data, -1);
    (void)result1; // Use volatile to prevent optimization

    // Test out-of-bounds read with index beyond array size
    printf("Testing index beyond array: 32\n");
    volatile float result2 = get_sensor_value(sensor_data, 32);
    (void)result2;

    printf("Testing index beyond array: 50\n");
    volatile float result3 = get_sensor_value(sensor_data, 50);
    (void)result3;

    printf("Testing large negative index: -100\n");
    volatile float result4 = get_sensor_value(sensor_data, -100);
    (void)result4;

    printf("Security tests completed. If sanitizers are enabled, out-of-bounds reads will be reported.\n");
    return 0;
}

